/// `move.flags.failmimic`.
pub fn fail_mimic(m: Choices) -> bool {
    matches!(
        m,
        Choices::BELCH
        | Choices::BEHEMOTHBASH
        | Choices::BEHEMOTHBLADE
        | Choices::BLAZINGTORQUE
        | Choices::CELEBRATE
        | Choices::COMBATTORQUE
        | Choices::DYNAMAXCANNON
        | Choices::HOLDHANDS
        | Choices::MAGICALTORQUE
        | Choices::METRONOME
        | Choices::MIMIC
        | Choices::NOXIOUSTORQUE
        | Choices::SKETCH
        | Choices::TERASTARSTORM
        | Choices::WICKEDTORQUE
        | Choices::ASSIST
        | Choices::CHATTER
        | Choices::COPYCAT
        | Choices::MEFIRST
        | Choices::MIRRORMOVE
        | Choices::NATUREPOWER
        | Choices::SLEEPTALK
        | Choices::STRUGGLE
        | Choices::TRANSFORM
    )
}
